              {
                "type": "text",
                "content": "EX01: 使用16顆LED燈，LED燈閃爍過去並重複3次"
              },
              {
                "type": "code",
                "content": "void setup() {\n  for (int led = 22; led <= 37; led++) {\n    pinMode(led, OUTPUT);\n  }\n}\n\nvoid loop() {\n  for (int a = 0; a <= 3; a++) {\n    for (int led = 22; led <= 37; led++) {\n      digitalWrite(led, HIGH);\n      delay(200);\n      digitalWrite(led, LOW);\n      delay(200);\n    }\n  }\n}"
              },
              {
                "type": "text",
                "content": "EX02: 使用16顆LED燈，LED燈閃爍過去 並 重複3次，在全部LED暗"
              },
              {
                "type": "code",
                "content": "void setup() {\n  for (int led = 22; led <= 37; led++) {\n    pinMode(led, OUTPUT);\n  }\n}\n\nvoid loop() {\n  for (int a = 0; a <= 3; a++) {\n    for (int led = 22; led <= 37; led++) {\n      digitalWrite(led, HIGH);\n      delay(200);\n      digitalWrite(led, LOW);\n      delay(200);\n    }\n  }\n\n  for (int led = 22; led <= 37; led++) {\n    digitalWrite(led, LOW);\n    delay(200);\n  }\n}"
              },
              {
                "type": "text",
                "content": "EX03: [錯誤寫法] 使用16顆LED燈，LED燈同時閃爍 並 重複3次後，在全部LED暗"
              },
              {
                "type": "code",
                "content": "void setup() {\n  for (int led = 22; led <= 37; led++) {\n    pinMode(led, OUTPUT);\n  }\n}\n\nvoid loop() {\n  for (int a = 0; a <= 3; a++) {\n    for (int led = 22; led <= 37; led++) {\n      digitalWrite(led, HIGH);\n      delay(200);\n    }\n\n    for (int led = 22; led <= 37; led++) {\n      digitalWrite(led, LOW);\n      delay(200);\n    }\n  }\n\n  for (int led = 22; led <= 37; led++) {\n    digitalWrite(led, LOW);\n    delay(200);\n  }\n}"
              },
              {
                "type": "text",
                "content": "EX04: 使用16顆LED燈，LED燈同時閃爍 並 重複3次後，在全部LED暗。\n提醒：延遲放錯地方，效果差很多！"
              },
              {
                "type": "code",
                "content": "void setup() {\n  for (int led = 22; led <= 37; led++) {\n    pinMode(led, OUTPUT);\n  }\n}\nvoid loop() {\n  for (int a = 0; a <= 3; a++) {\n    for (int led = 22; led <= 37; led++) {\n      digitalWrite(led, HIGH);\n    }\n    delay(200);\n\n    for (int led = 22; led <= 37; led++) {\n      digitalWrite(led, LOW);\n    }\n    delay(200);\n  }\n\n\tfor (int led = 22; led <= 37; led++) {\n    digitalWrite(led, LOW);\n    delay(200);\n  }\n}"
              }
