                "type": "code",
                "content": "int r = 9;\nint g = 10;\nint b = 11;\n\nvoid setup() {\n  pinMode(r, OUTPUT);\n  pinMode(g, OUTPUT);\n  pinMode(b, OUTPUT);\n}\n\nvoid loop() {\n  RGB(0, 0, 0);  //調色\n}\nvoid RGB(int red, int green, int blue) {  //副程式，編排顏色位置\n  analogWrite(r, red);\n  analogWrite(g, green);\n  analogWrite(b, blue);\n}"
