                "type": "code",
                "content": "#define R 11\n#define G 10\n#define B 9\n\nvoid setup() {\n  pinMode(R, OUTPUT);\n  pinMode(G, OUTPUT);\n  pinMode(B, OUTPUT);\n}\n\nvoid loop() {\n  int red = 0;\n  int green = 0;\n  int blue = 0;\n\n  red = random(0, 255);\n  green = random(0, 255);\n  blue = random(0, 255);\n  \n  analogWrite(R, red);\n  analogWrite(G, green);\n  analogWrite(B, blue);\n  delay(1000);\n}"
