              {
                "type": "text",
                "content": "X01: 使用8顆LED燈，2個一組，LED1.2亮、LED3.4暗、LED5.6亮、LED7.8暗"
              },
              {
                "type": "code",
                "content": "void setup() {\n  pinMode(9, OUTPUT);\n  pinMode(10, OUTPUT);\n  pinMode(11, OUTPUT);\n}\n\nvoid loop() {\n  digitalWrite(10, 0); // 平台\n  vcc(); vcc();\n  gnd(); gnd();\n  vcc(); vcc();\n  gnd(); gnd();\n  digitalWrite(10, 1); // 平台\n}\n\nvoid vcc() {\n  digitalWrite(11, 0); // 位子\n  digitalWrite(9, 1);  // 資料\n  digitalWrite(11, 1); // 位子\n}\n\nvoid gnd() {\n  digitalWrite(11, 0); // 位子\n  digitalWrite(9, 0);  // 資料\n  digitalWrite(11, 1); // 位子\n}"
              },
              {
                "type": "text",
                "content": "EX02: 七段顯示器 顯示數字0"
              },
              {
                "type": "code",
                "content": "void setup() {\n  pinMode(9, OUTPUT);\n  pinMode(10, OUTPUT);\n  pinMode(11, OUTPUT);\n}\n\nvoid loop() {\n  digitalWrite(10, 0);\n  vcc(); vcc();\n  vcc(); vcc();\n  vcc(); vcc();\n  gnd(); gnd();\n  digitalWrite(10, 1);\n}\n\nvoid vcc() {\n  digitalWrite(11, 0);\n  digitalWrite(9, 1);\n  digitalWrite(11, 1);\n}\n\nvoid gnd() {\n  digitalWrite(11, 0);\n  digitalWrite(9, 0);\n  digitalWrite(11, 1);\n}"
              },
              {
                "type": "text",
                "content": "EX03: 七段顯示器 顯示數字7"
              },
              {
                "type": "code",
                "content": "void setup() {\n  pinMode(9, OUTPUT);\n  pinMode(10, OUTPUT);\n  pinMode(11, OUTPUT);\n}\n\nvoid loop() {\n  digitalWrite(10, 0);\n  vcc(); vcc();\n  vcc(); gnd();\n  gnd(); gnd();\n  gnd(); gnd();\n  digitalWrite(10, 1);\n}\n\nvoid vcc() {\n  digitalWrite(11, 0);\n  digitalWrite(9, 1);\n  digitalWrite(11, 1);\n}\n\nvoid gnd() {\n  digitalWrite(11, 0);\n  digitalWrite(9, 0);\n  digitalWrite(11, 1);\n}"
              }
