            "blocks": [
              {
                "type": "text",
                "content": "💽影片名稱：[Arduino寫程式] 第24集 - 指撥開關 對應控制\n🎬集數：24集"
              },
              {
                "type": "text",
                "content": "電路圖"
              },
              {
                "type": "image",
                "content": "https://lh3.googleusercontent.com/pw/AP1GczOGGkG-UfwLV-_NNkn2qTqKIrZ4odPh70cdmzsgwJRhpfYjn8YW8BldJ4m18-3zBm48tS0LWO7jAYDlPMaZXXORs1E7iYbm5Mc01692KDCbU31F9K-JljXwGavxMWM3BwcLzfqMAtwRr18Y8QEJOXd4=w917-h688-s-no-gm?authuser=0"
              },
              {
                "type": "text",
                "content": "▲ 電路圖由 @CCplus2561 提供"
              },
              {
                "type": "text",
                "content": "EX01:   開關1控制LED1.2亮 / 開關2控制LED3.4亮"
              },
              {
                "type": "code",
                "content": "int k1, k3;\n\nvoid setup() {\n  for (int a = 11; a <= 13; a++) {\n    pinMode(a, INPUT);      // 輸入腳位 11~13 (開關)\n  }\n  for (int b = 22; b <= 25; b++) { \n    pinMode(b, OUTPUT);     // 修正：拼字錯誤 pinMoed -> pinMode，輸出腳位 22~25 (LED)\n  }\n}\n\nvoid loop() {\n  // 開關 1 (腳位 13) 控制 LED 1、2 (腳位 22, 23)\n  k1 = digitalRead(13);\n  if (k1 == 1) {             // 開關 1 按下：22、23 點亮\n    digitalWrite(22, 1);\n    digitalWrite(23, 1);\n  } else {                   // 開關 1 放開：22、23 熄滅\n    digitalWrite(22, 0);\n    digitalWrite(23, 0);\n  }\n\n  // 開關 3 (腳位 11) 控制 LED 3、4 (腳位 24, 25)\n  k3 = digitalRead(11);\n  if (k3 == 1) {             // 開關 3 按下：24、25 點亮\n    digitalWrite(24, 1);\n    digitalWrite(25, 1);\n  } else {                   // 開關 3 放開：24、25 熄滅\n    digitalWrite(24, 0);\n    digitalWrite(25, 0);\n  }\n}"
              },
              {
                "type": "text",
                "content": "EX02:   開關1控制LED亮與暗/開關3控制LED閃爍"
              },
              {
                "type": "code",
                "content": "int k1, k3;\n\nvoid setup() {\n  for (int a = 11; a <= 13; a++) {\n    pinMode(a, INPUT);      // 輸入腳位 11~13 (開關)\n  }\n  for (int b = 22; b <= 25; b++) {\n    pinMode(b, OUTPUT);     // 修正 1：拼字錯誤 pinMoed -> pinMode\n  }\n}\n\nvoid loop() {\n  k1 = digitalRead(13);\n  k3 = digitalRead(11);\n\n  if ((k1 == 1) && (k3 != 1)) {        // 修正 2：補齊條件式右括號 )\n    // 開關 1 開、開關 3 關：22, 23 亮，其餘暗\n    digitalWrite(22, 1);\n    digitalWrite(23, 1);\n    digitalWrite(24, 0);\n    digitalWrite(25, 0);\n  } \n  else if ((k1 != 1) && (k3 == 1)) {   // 修正 2：補齊條件式右括號 )；修正 3：補齊 else if 區塊的右大括號 }\n    // 開關 1 關、開關 3 開：24, 25 亮，其餘暗\n    digitalWrite(22, 0);\n    digitalWrite(23, 0);\n    digitalWrite(24, 1);\n    digitalWrite(25, 1);\n  } \n  else {\n    // 兩開關皆未按，或兩開關同時按下時：全部熄滅\n    digitalWrite(22, 0);\n    digitalWrite(23, 0);\n    digitalWrite(24, 0);\n    digitalWrite(25, 0);\n  }\n}"
              }
            ],
