              {
                "type": "text",
                "content": "EX01:  按一下亮.暗一下暗"
              },
              {
                "type": "code",
                "content": "int pin = 1; // 儲存 LED 當前狀態 (1 表示高電位 / 0 表示低電位)\n\nvoid setup() {\n  pinMode(13, OUTPUT);      // 腳位 13 設為輸出 (控制 LED)\n  pinMode(7, INPUT_PULLUP); // 修正 3：建議改用內建上拉電阻，避免腳位浮空\n}\n\nvoid loop() {\n  // 修正 1：補齊條件式中的比較值 (LOW / 0)\n  if (digitalRead(7) == LOW) { \n    pin = !pin;            // 修正 2：翻轉狀態 (1 變 0，0 變 1)\n    digitalWrite(13, pin); // 寫入新狀態至 LED\n    \n    delay(200);            // 建議加入簡短延遲，防止按鍵彈跳 (Debounce)\n  }\n}"
              }
