                "type": "code",
                "content": "#define Do 523\n#define Re 587\n#define Mi 659\n#define Fa 698\n#define So 784\n#define La 880\n#define Si 988\n\nint s1[] = {So, Mi, Mi, Fa, Re, Re};\nint s2[] = {Do, Re, Mi, Fa, So, La, Si};\n\nvoid setup() {\n\n}\n\nvoid loop() {\n  for (int i = 0; i <= 6; i++) {\n    tone(7, s1[i]);\n    delay(500);\n  }\n  noTone(7);\n  delay(1000);\n\n  for (int i = 0; i <= 7; i++) {\n    tone(7, s2[i]);\n    delay(500);\n  }\n  noTone(7);\n  delay(1000);\n}"
