              {
                "type": "code",
                "content": "#include <LiquidCrystal.h> //lcd函式庫\n\nLiquidCrystal lcd(12, 11, 5, 4, 3, 2); //LCD分別腳位\n\nvoid setup() {\n  lcd.begin(16, 2); //16字.2行\n}\n\nvoid loop() {\n  lcd.setCursor(1, 0); //第1行第1個顯示位子\n  lcd.print(\"Hi~ Arduino\");\n  delay(1000);\n\n  lcd.setCursor(5, 1); //第2行第5個顯示位\n  lcd.print(\"I am is ALO\");\n  delay(1000);\n}"
              },
              {
                "type": "text",
                "content": "EX02: 顯示文字並閃爍"
              },
              {
                "type": "code",
                "content": "#include <LiquidCrystal.h> //lcd函式庫\n\nLiquidCrystal lcd(12, 11, 5, 4, 3, 2); //LCD分別腳位\n\nvoid setup() {\n  lcd.begin(16, 2); //16字.2行\n}\n\nvoid loop() {\n  lcd.setCursor(1, 0); //第1行第1個顯示位子\n  lcd.print(\"Hi~ Arduino\");\n  delay(1000);\n\n  lcd.setCursor(5, 1); //第2行第5個顯示位\n  lcd.print(\"I am is ALO\");\n  delay(1000);\n\n  lcd.noDisplay(); //關閉LCD顯示\n  delay(1000);\n\n  lcd.display();   //開啟LCD顯示\n  delay(1000);\n}"
              }
