              {
                "type": "image",
                "content": "https://lh3.googleusercontent.com/pw/AP1GczNi7hl_GPz_cf34exyVjEmefJcdMtqV-SQECWQ-iYo-PfosoZ35QZRRQHyRIb9v_tiuwbD1oZ_gWE93YS5vNsAFEqXv7S9NfG8xxTDIeAWSPQKqPjnky_QG7NKuINJC1oz-feIhhFGyOkcXv63ltql4=w871-h653-s-no-gm?authuser=0"
              },
              {
                "type": "text",
                "content": "▲ 腳位圖由 @CCplus2561 提供"
              },
              {
                "type": "text",
                "content": "EX01:  紅外線訊號轉為10進位"
              },
              {
                "type": "code",
                "content": "#include <IRremote.h>        //紅外線函式庫\n\nIRrecv irrecv(2);           //紅外線腳位\ndecode_results IR;          //宣告變數\n\nvoid setup() {\n  Serial.begin(9600);       //開啟序列附視窗.設定成9600\n  irrecv.enableIRIn();      //啟動紅外線解碼\n}\n\nvoid loop() {\n  if (irrecv.decode(&IR)) {        //如果接收到紅外線訊號\n    Serial.print(\"接收代碼為:\");  //顯示\n    Serial.print(IR.value);        //與上面文字合併.以十進位顯示\n    Serial.print(\",位元數:\");    //顯示在同一行\n    Serial.println(IR.bits);       //代入上一行並探測位元碼\n    irrecv.resume();               //繼續接收下一個紅外線訊號\n  }\n}"
              },
              {
                "type": "text",
                "content": "EX02:  紅外線訊號轉為2進位"
              },
              {
                "type": "code",
                "content": "#include <IRremote.h>        //紅外線函式庫\n\nIRrecv irrecv(2);           //紅外線腳位\ndecode_results IR;          //宣告變數\n\nvoid setup() {\n  Serial.begin(9600);       //開啟序列附視窗.設定成9600\n  irrecv.enableIRIn();      //啟動紅外線解碼\n}\n\nvoid loop() {\n  if (irrecv.decode(&IR)) {        //如果接收到紅外線訊號\n    Serial.print(\"接收代碼為:\");  //顯示\n    Serial.print(IR.value, BIN);   //與上面文字合併.以二進位顯示\n    Serial.print(\",位元數:\");    //顯示在同一行\n    Serial.println(IR.bits);       //代入上一行並探測位元碼\n    irrecv.resume();               //繼續接收下一個紅外線訊號\n  }\n}"
              },
              {
                "type": "text",
                "content": "EX03:  紅外線訊號轉為16進位"
              },
              {
                "type": "code",
                "content": "#include <IRremote.h>        //紅外線函式庫\n\nIRrecv irrecv(2);           //紅外線腳位\ndecode_results IR;          //宣告變數\n\nvoid setup() {\n  Serial.begin(9600);       //開啟序列附視窗.設定成9600\n  irrecv.enableIRIn();      //啟動紅外線解碼\n}\n\nvoid loop() {\n  if (irrecv.decode(&IR)) {        //如果接收到紅外線訊號\n    Serial.print(\"接收代碼為:\");  //顯示\n    Serial.print(IR.value, HEX);   //與上面文字合併.以十六進位顯示\n    Serial.print(\",位元數:\");    //顯示在同一行\n    Serial.println(IR.bits);       //代入上一行並探測位元碼\n    irrecv.resume();               //繼續接收下一個紅外線訊號\n  }\n}"
              },
              {
                "type": "text",
                "content": "EX04:  紅外線訊號控制LED燈"
              },
              {
                "type": "code",
                "content": "#include <IRremote.h>        //紅外線函式庫\n\nIRrecv irrecv(2);           //紅外線腳位\ndecode_results IR;          //宣告變數\n\nvoid setup() {\n  pinMode(3, OUTPUT);       //宣告使用LED燈\n  Serial.begin(9600);       //開啟序列埠視窗，設定成9600\n  irrecv.enableIRIn();      //啟動紅外線解碼\n}\n\nvoid loop() {\n  if (irrecv.decode(&IR)) {        //如果接收到紅外線訊號\n    if (IR.value == 16718055) {    //如果讀取到按鈕1（開燈指令）\n      digitalWrite(3, 1);          //LED亮\n    }\n    if (IR.value == 16730805) {    //如果讀取到按鈕2（關燈指令）\n      digitalWrite(3, 0);          //LED暗\n    }\n    irrecv.resume();               //繼續接收下一個紅外線訊號\n  }\n  delay(200);\n}"
              }
